'EPIC-023'; from __future__ import annotations; import json; from decimal import Decimal; from pathlib import Path; from common.testing import preflight; from common.testing.check_llm_cassettes import _IN_DIRECTIONS, _OUT_DIRECTIONS, balance_violation, check, exempt_count, VALIDATION_SOURCE, production_direction_aliases, _response_text
def test_AC23_7_1_committed_cassettes_satisfy_balance_chain() -> None: 'AC-llm.7.1'; assert check() == []; 'AC-llm.7.1'; 'AC-llm.7.1'; _m1_good = {'opening_balance': '100.00', 'closing_balance': '130.00', 'transactions': [{'amount': '-5.00'}, {'amount': '+50.00'}, {'amount': '-15.00'}]}; assert balance_violation(_m1_good) is None; _m1_drifted = {'opening_balance': '100.00', 'closing_balance': '130.00', 'transactions': [{'amount': '-5.00'}]}; assert balance_violation(_m1_drifted) is not None; 'AC-llm.7.1'; 'AC-llm.7.1'; _m2_source = VALIDATION_SOURCE.relative_to(Path(__file__).resolve().parents[2]); _m2_checks = preflight.select_checks([_m2_source.as_posix()]); assert 'llm-cassettes' in {check.name for check in _m2_checks}; 'AC-llm.7.1'; 'AC-llm.7.1'; _m3_directional = {'opening_balance': '100.00', 'closing_balance': '130.00', 'transactions': [{'amount': '5.00', 'direction': 'OUT'}, {'amount': '50.00', 'direction': 'IN'}, {'amount': '15.00', 'direction': 'OUT'}]}; assert balance_violation(_m3_directional) is None; _m3_all_in = {'opening_balance': '100.00', 'closing_balance': '130.00', 'transactions': [{'amount': '5.00', 'direction': 'IN'}, {'amount': '50.00', 'direction': 'IN'}, {'amount': '15.00', 'direction': 'IN'}]}; assert balance_violation(_m3_all_in) is not None; 'AC-llm.7.1'; 'AC-llm.7.1'; _m4_payload = {'opening_balance': '0.00', 'closing_balance': '0.30', 'transactions': [{'amount': '0.10'}, {'amount': '0.10'}, {'amount': '0.10'}]}; assert balance_violation(_m4_payload) is None; assert Decimal('0.10') * 3 == Decimal('0.30'); 'AC-llm.7.1'; 'AC-llm.7.1'; assert _response_text({'stream_text': 'abc'}) == 'abc'; assert _response_text({'text': 'xyz'}) == 'xyz'; assert _response_text({'choices': [{'message': {'content': 'deep'}}]}) == 'deep'; assert _response_text('raw') == 'raw'; assert _response_text({'nothing': 1}) is None
def test_AC23_7_1_direction_aliases_are_read_from_the_production_parser(tmp_path): 'AC-llm.7.1'; from src.extraction.base import validation; assert _IN_DIRECTIONS == frozenset(validation.IN_DIRECTION_ALIASES); assert _OUT_DIRECTIONS == frozenset(validation.OUT_DIRECTION_ALIASES); source = tmp_path / 'validation.py'; source.write_text('IN_DIRECTION_ALIASES = {"X"}\nOUT_DIRECTION_ALIASES = {"Y"}\n'); assert production_direction_aliases(source) == ({'X'}, {'Y'}); 'AC-llm.7.1'; _m5_tmp = tmp_path / '_m5'; _m5_tmp.mkdir(exist_ok=True); 'AC-llm.7.1'; _write_statement_cassette(_m5_tmp, 'a' * 8, reconciles=False); assert check(_m5_tmp) == []; assert exempt_count(_m5_tmp) == 1; _m5_other = _m5_tmp / 'sub'; _m5_other.mkdir(); _write_statement_cassette(_m5_other, 'b' * 8, reconciles=True); assert check(_m5_other) != []; assert exempt_count(_m5_other) == 0
def _write_statement_cassette(cassette_dir: Path, fp: str, *, reconciles: bool) -> None:
    (cassette_dir / f'{fp}.json').write_text(json.dumps({'fingerprint': fp, 'role': 'text', 'response': {'stream_text': json.dumps({'opening_balance': '100.00', 'closing_balance': '130.00', 'transactions': [{'amount': '-5.00'}]})}}), encoding='utf-8')
    if reconciles is False: gt = cassette_dir / 'ground_truth'; gt.mkdir(exist_ok=True); (gt / f'{fp}.truth.json').write_text(json.dumps({'synthetic': True, 'balance_reconciles': False}), encoding='utf-8')
def test_AC23_7_1_missing_or_empty_cassette_dir_fails_closed(tmp_path: Path, capsys) -> None: 'AC-llm.7.1'; from common.testing.check_llm_cassettes import main as gate_main; missing_dir = tmp_path / 'no-such-cassettes'; assert gate_main(['--cassette-dir', str(missing_dir)]) == 1; captured_missing = capsys.readouterr(); assert '::error title=LLM cassette integrity::' in captured_missing.err; empty_dir = tmp_path / 'empty-cassettes'; empty_dir.mkdir(); assert gate_main(['--cassette-dir', str(empty_dir)]) == 1; captured_empty = capsys.readouterr(); assert '::error title=LLM cassette integrity::' in captured_empty.err; assert gate_main([]) == 0; captured_ok = capsys.readouterr(); assert '[CASSETTE] PASSED:' in captured_ok.out
